19	func get(template string, trusted bool, context any) *Text {
20		if textPool == nil {
21			// Fallback if pool is not initialized yet
22			return &Text{context: context, template: template, trusted: trusted}
23		}
24	
25		text := textPool.Get()
26		text.template = template
27		text.trusted = trusted
28		text.context = context
