33	// RenderTrusted executes a template the caller has verified was authored by
34	// the user in their own configuration (a segment/block/palette/etc. template
35	// field), as opposed to text assembled at runtime from external data
36	// (filesystem names, command output, API responses, ...). The full func map
37	// is available, including cmd/readFile/stat/glob.
38	//
39	// Only call this with a string read verbatim from a config field — passing
40	// runtime-composed text here defeats the whole point of the split with
41	// RenderUntrusted.
42	func RenderTrusted(template string, context any) (string, error) {
43		return render(template, true, context)
44	}
45	
46	// RenderUntrusted executes a template that may contain, or be composed from,
47	// runtime data rather than user-authored config text. cmd/readFile/stat/glob
48	// and env/expandenv are not available.
49	func RenderUntrusted(template string, context any) (string, error) {
50		return render(template, false, context)
51	}
