53	func render(template string, trusted bool, context any) (string, error) {
54		t := get(template, trusted, context)
55		defer t.release()
56	
57		if !strings.Contains(t.template, "{{") || !strings.Contains(t.template, "}}") {
58			return t.template, nil
59		}
60	
61		renderer := renderPool.Get()
62		defer renderer.release()
63	
64		return renderer.execute(t)
65	}
