77	func (t *Text) patchTemplate() {
78		fields := &fields{}
79		fields.init(t.context)
80	
81		var result, property strings.Builder
82		var inProperty, inTemplate bool
83		for i, char := range t.template {
84			// define start or end of template
85			if !inTemplate && char == '{' {
86				if i-1 >= 0 && rune(t.template[i-1]) == '{' {
87					inTemplate = true
88				}
89			} else if inTemplate && char == '}' {
90				if i-1 >= 0 && rune(t.template[i-1]) == '}' {
91					inTemplate = false
92				}
93			}
94	
95			if !inTemplate {
96				result.WriteRune(char)
97				continue
98			}
99	
100			switch char {
101			case '.':
102				var lastChar rune
103				rs := result.String()
104				if len(rs) > 0 {
105					lastChar = rune(rs[len(rs)-1])
106				}
107				// only replace if we're in a valid property start
108				// with a space, { or ( character
109				switch lastChar {
110				case ' ', '{', '(':
111					property.WriteRune(char)
112					inProperty = true
113				default:
114					result.WriteRune(char)
115				}
116			case ' ', '}', ')': // space or }
117				if !inProperty {
118					result.WriteRune(char)
119					continue
120				}
121	
122				prop := property.String()
123				switch {
124				case strings.HasPrefix(prop, ".Segments") && !strings.HasSuffix(prop, ".Contains"):
125					// as we can't provide a clean way to access the list
126					// of segments, we need to replace the property with
127					// the list of segments so they can be accessed directly
128					parts := strings.Split(prop, ".")
129					if len(parts) > 3 {
130						fmt.Fprintf(&result, `(.Segments.MustGet "%s").%s`, parts[2], strings.Join(parts[3:], "."))
131					} else {
132						fmt.Fprintf(&result, `(.Segments.MustGet "%s")`, parts[2])
133					}
134					// property = strings.Replace(property, ".Segments", ".Segments.ToSimple", 1)
135					// result += property
136				case strings.HasPrefix(prop, ".Env."):
137					// we need to replace the property with the getEnv function
138					// so we can access the environment variables directly
139					fmt.Fprintf(&result, `(call .Getenv "%s")`, strings.TrimPrefix(prop, ".Env."))
140				default:
141					// check if we have the same property in Data
142					// and replace it with the Data property so it
143					// can take precedence
144					if fields.hasField(prop) {
145						result.WriteString(".Data")
146					}
147	
148					// remove the global reference so we can use it directly
149					result.WriteString(strings.TrimPrefix(prop, globalRef))
150				}
151	
152				property.Reset()
153				result.WriteRune(char)
154				inProperty = false
155			default:
156				if inProperty {
157					property.WriteRune(char)
158					continue
159				}
160				result.WriteRune(char)
161			}
162		}
163	
164		// return the result and remaining unresolved property
165		t.template = result.String() + property.String()
166	
167		log.Debug(t.template)
168	}
