170	// Immutable once built and stored in knownFields — never mutated afterward.
171	type fieldSet map[string]bool
172	
173	// For struct types the set is shared from knownFields (immutable, no copy
174	// needed). For map types it is built locally and not shared.
175	type fields struct {
176		values fieldSet
177	}
178	
179	// Recursive over embedded struct fields. May be called concurrently for the
180	// same type; LoadOrStore ensures only one result is shared.
181	func initFromType(typ reflect.Type) fieldSet {
182		if cached, ok := knownFields.Load(typ); ok {
183			return cached.(fieldSet)
184		}
185	
186		set := make(fieldSet)
187	
188		// Get struct fields and check embedded types
189		for field := range typ.Fields() {
190			if r, _ := utf8.DecodeRuneInString(field.Name); unicode.IsUpper(r) {
191				set[field.Name] = true
192			}
193	
194			// If this is an embedded field, merge its fields recursively
195			if !field.Anonymous {
196				continue
197			}
198	
199			embedded := field.Type
200			if embedded.Kind() == reflect.Pointer {
201				embedded = embedded.Elem()
202			}
203	
204			if embedded.Kind() == reflect.Struct {
205				for k := range initFromType(embedded) {
206					set[k] = true
207				}
208			}
209		}
210	
211		// Get pointer methods
212		ptrType := reflect.PointerTo(typ)
213		for method := range ptrType.Methods() {
214			name := method.Name
215			if r, _ := utf8.DecodeRuneInString(name); unicode.IsUpper(r) {
216				set[name] = true
217			}
218		}
219	
220		// Store atomically; if another goroutine won the race, discard ours and use theirs.
221		actual, _ := knownFields.LoadOrStore(typ, set)
222		return actual.(fieldSet)
223	}
224	
225	func (f *fields) init(data any) {
226		if data == nil {
227			return
228		}
229	
230		val := reflect.TypeOf(data)
231		switch val.Kind() {
232		case reflect.Struct:
233			// Shared immutable set — no copy needed.
234			f.values = initFromType(val)
235		case reflect.Map:
236			m, ok := data.(map[string]any)
237			if !ok {
238				return
239			}
240			set := make(fieldSet, len(m))
241			for key := range m {
242				if r, _ := utf8.DecodeRuneInString(key); unicode.IsUpper(r) {
243					set[key] = true
244				}
245			}
246			f.values = set
247		case reflect.Pointer:
248			v := reflect.ValueOf(data)
249			if v.IsNil() {
250				return
251			}
252	
253			f.init(v.Elem().Interface())
254		default:
255		}
256	}
257	
258	func (f *fields) hasField(field string) bool {
259		if f.values == nil {
260			return false
261		}
262	
263		field = strings.TrimPrefix(field, ".")
264	
265		// get the first part of the field
266		field, _, _ = strings.Cut(field, ".")
267	
268		_, ok := f.values[field]
269		return ok
270	}
