375	func FormatTitle(title string) string {
376		switch Shell {
377		// These shells don't support setting the console title.
378		case shell.ELVISH, shell.XONSH:
379			return ""
380		case shell.BASH, shell.ZSH, shell.YASH:
381			title = trimAnsi(title)
382	
383			sb := text.NewBuilder()
384	
385			// We have to do this to prevent the shell from misidentifying escape sequences.
386			for _, char := range title {
387				escaped, shouldEscape := formats.EscapeSequences[char]
388				if shouldEscape {
389					sb.WriteString(escaped)
390					continue
391				}
392	
393				sb.WriteRune(char)
394			}
395	
396			return fmt.Sprintf(formats.Title, sb.String())
397		default:
398			return fmt.Sprintf(formats.Title, trimAnsi(title))
399		}
400	}
